<!doctype html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>@yield('title') · ZeleBoba</title>
<style>:root{--ink:#182c29;--muted:#687773;--line:#dee6e2;--green:#135d45;--bg:#f5f7f6}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 system-ui,sans-serif}.main{max-width:1000px;margin:auto;padding:42px 24px}a{color:var(--green)}header{display:flex;justify-content:space-between;align-items:center;gap:18px}.panel{background:#fff;border:1px solid var(--line);border-radius:12px;padding:28px;margin-top:24px}.panel article{padding:12px 0;border-bottom:1px solid var(--line)}.panel article:last-child{border:0}.muted{color:var(--muted)}button{border:0;border-radius:6px;padding:9px 14px;background:var(--green);color:white;font:inherit}.timeline{list-style:none;margin:0;padding:2px 0}.timeline li{display:grid;grid-template-columns:64px 1fr;gap:14px;padding:10px 0 10px 19px;border-left:2px solid #b9d8c8;position:relative}.timeline li:before{content:'';width:9px;height:9px;border-radius:50%;background:var(--green);position:absolute;left:-5.5px;top:17px}.timeline li:last-child{border-left-color:transparent}.timeline time{color:var(--muted);font-variant-numeric:tabular-nums;font-size:14px}</style></head>
<body><main class="main">@yield('content')</main></body></html>
